import React, { useState } from 'react';
import { Send, Phone, User, CheckCheck, ArrowLeft, MoreVertical } from 'lucide-react';

export default function MessagesPage() {
  const [activeChat, setActiveChat] = useState(1);
  const [inputText, setInputText] = useState('');

  const [conversations, setConversations] = useState([
    {
      id: 1,
      name: "তানভীর আহমেদ",
      bloodGroup: "O+",
      avatar: "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=150",
      phone: "01711000000",
      lastMessage: "আমি বিকেল ৪টায় হাসপাতালে পৌঁছাতে পারব।",
      time: "১০:৩০ AM",
      unread: 0,
      messages: [
        { id: 1, sender: "them", text: "আসসালামু আলাইকুম, রক্ত কি এখনও প্রয়োজন?", time: "১০:২৪ AM" },
        { id: 2, sender: "me", text: "ওয়া আলাইকুমুস সালাম, হ্যাঁ ভাই! ঢাকা মেডিকেলে O+ প্রয়োজন।", time: "১০:২৫ AM" },
        { id: 3, sender: "them", text: "আমি বিকেল ৪টায় হাসপাতালে পৌঁছাতে পারব।", time: "১০:৩০ AM" }
      ]
    },
    {
      id: 2,
      name: "মেহেদী হাসান",
      bloodGroup: "A+",
      avatar: "https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=150",
      phone: "01811000000",
      lastMessage: "রোগীর বর্তমান অবস্থা কেমন?",
      time: "গতকাল",
      unread: 2,
      messages: [
        { id: 1, sender: "them", text: "রোগীর বর্তমান অবস্থা কেমন?", time: "গতকাল" }
      ]
    }
  ]);

  const currentChat = conversations.find(c => c.id === activeChat);

  const handleSendMessage = (e) => {
    e.preventDefault();
    if (!inputText.trim()) return;

    const newMessage = {
      id: Date.now(),
      sender: 'me',
      text: inputText,
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };

    setConversations(conversations.map(chat => {
      if (chat.id === activeChat) {
        return {
          ...chat,
          lastMessage: inputText,
          time: 'এখনই',
          messages: [...chat.messages, newMessage]
        };
      }
      return chat;
    }));

    setInputText('');
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-4 h-[calc(100vh-5rem)] flex flex-col md:flex-row gap-4">
      
      {/* --- CONVERSATIONS LIST (LEFT SIDE) --- */}
      <div className={`w-full md:w-80 bg-white rounded-3xl border border-slate-100 p-4 shadow-sm flex flex-col ${activeChat ? 'hidden md:flex' : 'flex'}`}>
        <div className="pb-3 border-b border-slate-100 flex justify-between items-center">
          <h1 className="text-lg font-black text-slate-900">মেসেজসমূহ</h1>
          <span className="bg-rose-100 text-brand-700 font-bold text-xs px-2.5 py-0.5 rounded-full">
            {conversations.length} টি চ্যাট
          </span>
        </div>

        <div className="overflow-y-auto flex-1 space-y-2 pt-3">
          {conversations.map((chat) => (
            <div
              key={chat.id}
              onClick={() => setActiveChat(chat.id)}
              className={`p-3 rounded-2xl cursor-pointer transition flex items-center justify-between gap-3 ${
                activeChat === chat.id 
                  ? 'bg-rose-50 border border-rose-100' 
                  : 'hover:bg-slate-50'
              }`}
            >
              <div className="relative">
                <img src={chat.avatar} alt={chat.name} className="w-11 h-11 rounded-full object-cover" />
                <span className="absolute bottom-0 right-0 bg-brand-600 text-white text-[9px] font-black px-1 rounded-full">
                  {chat.bloodGroup}
                </span>
              </div>

              <div className="flex-1 min-w-0">
                <div className="flex justify-between items-center">
                  <h3 className="text-xs font-bold text-slate-900 truncate">{chat.name}</h3>
                  <span className="text-[10px] text-slate-400 font-medium">{chat.time}</span>
                </div>
                <p className="text-[11px] text-slate-500 font-medium truncate mt-0.5">{chat.lastMessage}</p>
              </div>

              {chat.unread > 0 && (
                <span className="w-5 h-5 rounded-full bg-brand-600 text-white text-[10px] font-bold flex items-center justify-center">
                  {chat.unread}
                </span>
              )}
            </div>
          ))}
        </div>
      </div>

      {/* --- ACTIVE CHAT BOX (RIGHT SIDE) --- */}
      <div className={`flex-1 bg-white rounded-3xl border border-slate-100 shadow-sm flex-col ${activeChat ? 'flex' : 'hidden md:flex'}`}>
        {currentChat ? (
          <>
            {/* Chat Top Header */}
            <div className="p-4 border-b border-slate-100 flex items-center justify-between">
              <div className="flex items-center gap-3">
                <button 
                  onClick={() => setActiveChat(null)} 
                  className="md:hidden p-1 text-slate-500 hover:text-slate-800"
                >
                  <ArrowLeft className="w-5 h-5" />
                </button>
                <img src={currentChat.avatar} alt={currentChat.name} className="w-10 h-10 rounded-full object-cover" />
                <div>
                  <h2 className="text-sm font-bold text-slate-900 flex items-center gap-1.5">
                    {currentChat.name}
                    <span className="bg-brand-600 text-white text-[10px] font-black px-2 py-0.5 rounded-full">
                      {currentChat.bloodGroup}
                    </span>
                  </h2>
                  <p className="text-[10px] text-emerald-600 font-bold">অনলাইন আছেন</p>
                </div>
              </div>

              <a
                href={`tel:${currentChat.phone}`}
                className="p-2.5 bg-rose-50 hover:bg-rose-100 text-brand-700 rounded-full transition"
                title="সরাসরি কল করুন"
              >
                <Phone className="w-4 h-4" />
              </a>
            </div>

            {/* Messages Body */}
            <div className="flex-1 p-4 overflow-y-auto space-y-3 bg-slate-50/50">
              {currentChat.messages.map((msg) => (
                <div
                  key={msg.id}
                  className={`flex flex-col ${msg.sender === 'me' ? 'items-end' : 'items-start'}`}
                >
                  <div
                    className={`max-w-[75%] px-4 py-2.5 rounded-2xl text-xs font-medium leading-relaxed shadow-sm ${
                      msg.sender === 'me'
                        ? 'bg-brand-600 text-white rounded-br-none'
                        : 'bg-white text-slate-800 border border-slate-100 rounded-bl-none'
                    }`}
                  >
                    {msg.text}
                  </div>
                  <span className="text-[9px] text-slate-400 font-medium mt-1 px-1 flex items-center gap-1">
                    {msg.time}
                    {msg.sender === 'me' && <CheckCheck className="w-3 h-3 text-brand-500" />}
                  </span>
                </div>
              ))}
            </div>

            {/* Input Form */}
            <form onSubmit={handleSendMessage} className="p-3 border-t border-slate-100 flex items-center gap-2">
              <input
                type="text"
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
                placeholder="একটি বার্তা লিখুন..."
                className="flex-1 bg-slate-50 border border-slate-200 rounded-2xl px-4 py-2.5 text-xs font-medium focus:outline-none focus:border-brand-600"
              />
              <button
                type="submit"
                className="bg-brand-600 hover:bg-brand-700 text-white p-2.5 rounded-2xl shadow-md shadow-brand-600/30 transition active:scale-95"
              >
                <Send className="w-4 h-4" />
              </button>
            </form>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center p-6 text-slate-400 text-xs font-medium">
            কথোপকথন শুরু করতে তালিকা থেকে যেকোনো একটি চ্যাট নির্বাচন করুন।
          </div>
        )}
      </div>

    </div>
  );
}
